package com.music.innertube

import com.music.innertube.models.PlayerResponse.Captions.CaptionTrack
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.contentOrNull
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.longOrNull

/** the auto-generated track or an uploaded one in its language, the auto track says which language is sung */
internal fun pickCaptionTrack(tracks: List<CaptionTrack>): CaptionTrack? {
    val auto = tracks.firstOrNull { it.isAutoGenerated } ?: return null
    val language = auto.languageCode?.substringBefore('-')
    return tracks.firstOrNull {
        !it.isAutoGenerated && it.languageCode?.substringBefore('-') == language
    } ?: auto
}

/** timed-text json (fmt=json3) as lrc, one line per caption, sound labels and note signs are not words */
internal fun timedTextToLrc(json: String): String {
    val events = runCatching {
        Json.parseToJsonElement(json).jsonObject["events"]?.jsonArray
    }.getOrNull() ?: return ""
    val lines = ArrayList<String>()
    var previous: String? = null
    for (event in events) {
        val cue = event.jsonObject
        val start = cue["tStartMs"]?.jsonPrimitive?.longOrNull ?: continue
        val segs = cue["segs"]?.jsonArray ?: continue
        val text = segs.joinToString("") {
            it.jsonObject["utf8"]?.jsonPrimitive?.contentOrNull.orEmpty()
        }
            .replace(SoundLabel, " ")
            .replace('♪', ' ')
            .replace(Whitespace, " ")
            .trim()
        // a rolling caption repeats its line as the next one scrolls in
        if (text.isEmpty() || text == previous) continue
        previous = text
        lines += "${stamp(start)}$text"
    }
    return lines.joinToString("\n")
}

private fun stamp(ms: Long): String =
    "[${(ms / 60_000).toString().padStart(2, '0')}:" +
        "${(ms / 1000 % 60).toString().padStart(2, '0')}." +
        "${(ms % 1000).toString().padStart(3, '0')}]"

private val SoundLabel = Regex("""\[[^\]]*\]""")
private val Whitespace = Regex("""\s+""")
